data.CSS:
@font-face { font-family:"Fraunces"; font-weight:600; font-display:swap; src:url("/fonts/fraunces-600.woff2") format("woff2"); }
@font-face { font-family:"Plus Jakarta Sans"; font-weight:200 800; font-display:swap; src:url("/fonts/plus-jakarta-sans-wght.woff2") format("woff2"); }
:root { --char:#2B2620; --olive:#3E4A2C; --leaf:#6E8A3A; --ember:#A8401E; --ember-hi:#C2552F; --cream:#FBF6EC; --linen:#F2E7D3; --ink:#2B2620; --muted:#5F5447; --rule:#E3D7C3;
  --display:"Fraunces", Georgia, serif; --body:"Plus Jakarta Sans", system-ui, sans-serif; }
* { box-sizing:border-box; }
body { margin:0; background:var(--cream); color:var(--ink); font:17px/1.7 var(--body); }
img { display:block; max-width:100%; height:auto; }
a { color:var(--ember); text-decoration-color:var(--leaf); text-underline-offset:.2em; }
a:hover { text-decoration-thickness:2px; }
h1, h2, h3 { font-family:var(--display); font-weight:600; color:var(--olive); line-height:1.15; margin:0 0 .5em; letter-spacing:-.01em; }
h1 { font-size:clamp(2.2rem, 4.4vw, 3.4rem); }
h2 { font-size:clamp(1.5rem, 2.6vw, 2.05rem); }
h3 { font-size:1.2rem; }
.e-wrap { max-width:70rem; margin:0 auto; padding:0 1.25rem; }
.e-narrow { max-width:46rem; }
.e-skip { position:absolute; left:1rem; top:-3rem; z-index:10; background:var(--linen); color:var(--ink); padding:.5rem 1rem; border-radius:.3rem; font-weight:700; }
.e-skip:focus { top:1rem; }
.e-header { background:var(--olive); color:var(--cream); border-bottom:4px solid var(--ember); }
.e-header .e-wrap { display:flex; flex-wrap:wrap; align-items:center; gap:1rem 2rem; padding-top:1rem; padding-bottom:1rem; }
.e-brand { font-family:var(--display); font-size:1.6rem; color:var(--cream); text-decoration:none; letter-spacing:.01em; }
.e-brand span { color:#E9B48A; }
.e-nav ul, .e-langs { display:flex; flex-wrap:wrap; gap:.25rem 1.4rem; list-style:none; margin:0; padding:0; }
.e-nav a, .e-langs a { color:var(--cream); text-decoration:none; font-weight:600; }
.e-nav a:hover, .e-langs a:hover { text-decoration:underline; text-decoration-color:#E9B48A; }
.e-nav a[aria-current=page] { text-decoration:underline; text-decoration-color:#E9B48A; text-decoration-thickness:2px; text-underline-offset:.4em; }
.e-nav a.is-ancestor { text-decoration:underline; text-decoration-color:rgba(251,246,236,.45); text-underline-offset:.4em; }
.e-langs { margin-left:auto; font-size:.85rem; }
.e-langs a { text-transform:uppercase; letter-spacing:.08em; border:1px solid rgba(251,246,236,.5); border-radius:999px; padding:.15rem .65rem; }
.e-hero { position:relative; background:var(--char); color:#fff; }
.e-hero img { width:100%; aspect-ratio:16/7; object-fit:cover; opacity:.78; }
.e-hero .e-hero-text { position:absolute; inset:auto 0 0 0; padding:2.75rem 0; background:linear-gradient(transparent, rgba(30,24,18,.9)); }
.e-hero h1 { color:#fff; max-width:42rem; }
.e-hero p { max-width:36rem; font-size:1.15rem; margin:0 0 1.25rem; }
.e-actions { display:flex; flex-wrap:wrap; gap:.75rem; }
.e-button { display:inline-block; background:var(--ember); color:#fff; font-weight:700; text-decoration:none; padding:.75rem 1.4rem; border-radius:999px; }
.e-button:hover { background:var(--ember-hi); }
.e-button-quiet { background:transparent; color:#fff; border:2px solid rgba(255,255,255,.8); }
.e-button-quiet:hover { background:rgba(255,255,255,.12); }
button.e-button { border:0; cursor:pointer; font:inherit; font-weight:700; }
.e-section { padding:3.5rem 0; }
.e-section + .e-section { border-top:1px solid var(--rule); }
.e-band { background:var(--linen); }
.e-lead { font-size:1.2rem; color:var(--muted); max-width:44rem; }
.e-cards { display:grid; gap:1.75rem; grid-template-columns:repeat(auto-fill, minmax(17rem, 1fr)); list-style:none; margin:2rem 0 0; padding:0; }
.e-cards-row { grid-template-columns:repeat(auto-fit, minmax(17rem, 1fr)); }
.e-card { background:#fff; border:1px solid var(--rule); border-radius:.6rem; overflow:hidden; display:flex; flex-direction:column; }
.e-card img { aspect-ratio:3/2; object-fit:cover; width:100%; }
.e-card-body { padding:1.1rem 1.25rem 1.4rem; }
.e-card h3 { margin-bottom:.35rem; }
.e-card p { margin:0 0 .5rem; color:var(--muted); }
.e-price { font-weight:700; color:var(--ember); white-space:nowrap; }
.e-card .e-price { color:var(--ember); margin:0; }
.e-split { display:grid; gap:2.5rem; grid-template-columns:minmax(0, 1fr) minmax(0, 1fr); align-items:center; }
.e-split img { border-radius:.6rem; }
.e-hours { display:grid; grid-template-columns:auto 1fr; gap:.5rem 1.5rem; margin:1.25rem 0 0; padding:1.25rem 1.5rem; max-width:34rem; background:#fff; border:1px solid var(--rule); border-left:4px solid var(--leaf); border-radius:.4rem; }
.e-hours dt { font-weight:700; color:var(--olive); }
.e-hours dd { margin:0; }
.e-figure { margin:0 0 2rem; }
.e-figure img { border-radius:.6rem; }
.e-prose p, .e-prose ul, .e-prose dl { margin:0 0 1.1rem; }
.e-prose dl { display:grid; grid-template-columns:auto 1fr; gap:.35rem 1.25rem; }
.e-prose dt { font-weight:700; color:var(--olive); }
.e-prose dd { margin:0; }
.e-page section + section { margin-top:2.5rem; }
.e-course { margin-top:2.75rem; }
.e-dishes { list-style:none; margin:1rem 0 0; padding:0; }
.e-dish { display:grid; grid-template-columns:1fr auto; gap:.25rem 1.5rem; align-items:start; padding:1.1rem 0; border-bottom:1px dashed var(--rule); }
.e-dish-pictured { grid-template-columns:7rem 1fr auto; }
.e-dish img { width:7rem; height:7rem; object-fit:cover; border-radius:.5rem; }
.e-dish h3 { margin:0 0 .2rem; }
.e-dish p { margin:0; color:var(--muted); }
.e-dish .e-dish-note { font-size:.9rem; color:var(--leaf); font-weight:600; margin-top:.25rem; }
.e-dish .e-price { color:var(--ember); font-size:1.05rem; }
.e-note { margin-top:2.5rem; padding:1rem 1.25rem; background:var(--linen); border-radius:.4rem; color:var(--muted); }
.e-people { display:grid; gap:1.75rem; grid-template-columns:repeat(auto-fill, minmax(16rem, 1fr)); list-style:none; margin:1.5rem 0 0; padding:0; }
.e-person img { width:100%; aspect-ratio:4/5; object-fit:cover; border-radius:.6rem; margin-bottom:.9rem; }
.e-person h3 { margin-bottom:.15rem; }
.e-role { margin:0 0 .5rem; color:var(--leaf); font-weight:700; }
.e-person p { color:var(--muted); }
.e-form { display:grid; gap:1rem; max-width:36rem; margin-top:1.5rem; }
.e-field { margin:0; }
.e-field label { display:block; font-weight:700; margin-bottom:.3rem; }
.e-field input, .e-field textarea { box-sizing:border-box; width:100%; padding:.65rem .8rem; font:inherit; color:var(--ink); background:#fff; border:1px solid var(--rule); border-radius:.4rem; }
.e-field textarea { min-height:7rem; }
.e-footer { background:var(--char); color:var(--linen); padding:2.5rem 0; margin-top:3rem; font-size:.95rem; }
.e-footer a { color:#fff; }
.e-footer .e-wrap { display:flex; flex-wrap:wrap; justify-content:space-between; gap:1rem; }
.e-footer p { margin:0; }
@media (max-width: 48rem) { .e-split { grid-template-columns:1fr; } .e-hero img { aspect-ratio:4/3; opacity:1; } .e-hero .e-hero-text { position:static; background:var(--char); padding:1.75rem 0 2rem; } .e-langs { margin-left:0; } .e-dish-pictured { grid-template-columns:5rem 1fr; } .e-dish-pictured .e-price { grid-column:2; } .e-dish img { width:5rem; height:5rem; } }
